import numpy as np
UFUNCS = [obj for obj in np._core.umath.__dict__.values() if isinstance(obj, np.ufunc)]
UFUNCS_UNARY = [uf for uf in UFUNCS if 'O->O' in uf.types]

class _Official_bench_ufunc_strides__AbstractBinary(_Official_common_Benchmark):
    params = []
    param_names = ['ufunc', 'stride_in0', 'stride_in1', 'stride_out', 'dtype']
    timeout = 10
    arrlen = 1000000
    data_finite = True
    data_denormal = False
    data_zeros = False

    def setup(self, ufunc, stride_in0, stride_in1, stride_out, dtype):
        ufunc_insig = f'{dtype}{dtype}->'
        if ufunc_insig + dtype not in ufunc.types:
            for st_sig in (ufunc_insig, dtype):
                test = [sig for sig in ufunc.types if sig.startswith(st_sig)]
                if test:
                    break
            if not test:
                raise NotImplementedError(f"Ufunc {ufunc} doesn't support binary input of dtype {dtype}") from None
            tin, tout = test[0].split('->')
        else:
            tin = dtype + dtype
            tout = dtype
        self.ufunc_args = []
        for i, (dt, stride) in enumerate(zip(tin, (stride_in0, stride_in1))):
            self.ufunc_args += [get_data(self.arrlen * stride, dt, i, zeros=self.data_zeros, finite=self.data_finite, denormal=self.data_denormal)[::stride]]
        for dt in tout:
            self.ufunc_args += [np.empty(stride_out * self.arrlen, dt)[::stride_out]]
        np.seterr(all='ignore')

    def time_binary(self, ufunc, stride_in0, stride_in1, stride_out, dtype):
        ufunc(*self.ufunc_args)

    def time_binary_scalar_in0(self, ufunc, stride_in0, stride_in1, stride_out, dtype):
        ufunc(self.ufunc_args[0][0], *self.ufunc_args[1:])

    def time_binary_scalar_in1(self, ufunc, stride_in0, stride_in1, stride_out, dtype):
        ufunc(self.ufunc_args[0], self.ufunc_args[1][0], *self.ufunc_args[2:])

class _Official_bench_ufunc_strides__AbstractUnary(_Official_common_Benchmark):
    params = []
    param_names = ['ufunc', 'stride_in', 'stride_out', 'dtype']
    timeout = 10
    arrlen = 1000000
    data_finite = True
