    data_zeros = False

    def setup(self, ufunc, stride_in, stride_out, dtype):
        arr_in = get_data(stride_in * self.arrlen, dtype, zeros=self.data_zeros, finite=self.data_finite, denormal=self.data_denormal)
        self.ufunc_args = [arr_in[::stride_in]]
        ufunc_insig = f'{dtype}->'
        if ufunc_insig + dtype not in ufunc.types:
            test = [sig for sig in ufunc.types if sig.startswith(ufunc_insig)]
            if not test:
                raise NotImplementedError(f"Ufunc {ufunc} doesn't support unary input of dtype {dtype}") from None
            tout = test[0].split('->')[1]
        else:
            tout = dtype
        for dt in tout:
            self.ufunc_args += [np.empty(stride_out * self.arrlen, dt)[::stride_out]]
        np.seterr(all='ignore')

    def time_unary(self, ufunc, stride_in, stride_out, dtype):
        ufunc(*self.ufunc_args)

